               WHERE [ID] = @ID_e52a891b2f4d
                  OR ([QueryID] = @QueryID_e52a891b2f4d AND [EntityID] = @EntityID_e52a891b2f4d))
EXEC [${mjSchema}].spCreateQueryEntity @ID = @ID_e52a891b2f4d,
  @QueryID = @QueryID_e52a891b2f4d,
  @EntityID = @EntityID_e52a891b2f4d,
  @DetectionMethod = @DetectionMethod_e52a891b2f4d,
  @AutoDetectConfidenceScore = @AutoDetectConfidenceScore_e52a891b2f4d;

GO

